BEGIN;
CREATE FUNCTION pg13_reports(w uuid,e text,start_time timestamptz,end_time timestamptz,account uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE gross numeric;allocated numeric;counted bigint;refund numeric;BEGIN
 PERFORM pg06_scope(w,e);
 IF account IS NOT NULL AND NOT EXISTS(SELECT 1 FROM financial_receiving_accounts WHERE workspace_id=w AND environment=e AND id=account) THEN RAISE EXCEPTION 'account unavailable' USING ERRCODE='P0002';END IF;
 IF start_time IS NULL OR end_time IS NULL OR end_time<=start_time OR end_time-start_time>interval '366 days' THEN RAISE EXCEPTION 'invalid report period' USING ERRCODE='22023';END IF;
 SELECT coalesce(sum(p.verified_amount_minor),0),count(*) INTO gross,counted FROM financial_payments p JOIN payment_attempts a ON a.id=p.attempt_id WHERE p.workspace_id=w AND p.environment=e AND p.verified_at>=start_time AND p.verified_at<end_time AND(account IS NULL OR a.receiving_account_id=account);
 SELECT coalesce(sum(x.amount_minor),0) INTO allocated FROM financial_allocations x JOIN financial_payments p ON p.id=x.payment_id JOIN payment_attempts a ON a.id=p.attempt_id WHERE p.workspace_id=w AND p.environment=e AND p.verified_at>=start_time AND p.verified_at<end_time AND(account IS NULL OR a.receiving_account_id=account);
 SELECT coalesce(sum(r.amount_minor),0) INTO refund FROM pg11_refunds r JOIN financial_payments p ON p.id=r.payment_id JOIN payment_attempts a ON a.id=p.attempt_id WHERE r.workspace_id=w AND r.environment=e AND r.created_at>=start_time AND r.created_at<end_time AND r.status='seller_reported_returned' AND(account IS NULL OR a.receiving_account_id=account);
 RETURN jsonb_build_object('currency','BDT','from',start_time,'to',end_time,'generated_at',now(),'timezone','UTC','verified_gross_minor',gross,'allocated_minor',allocated,'unallocated_minor',gross-allocated,'payment_count',counted,'seller_reported_returned_minor',refund,'refund_independently_verified',false,'net_settled_minor',NULL,
 'definition','Verified receipt volume, not SaaS revenue or provider settlement. Seller-reported returns are shown separately.',
 'methods',coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM(SELECT a.method,sum(p.verified_amount_minor) amount_minor,count(*) payment_count FROM financial_payments p JOIN payment_attempts a ON a.id=p.attempt_id WHERE p.workspace_id=w AND p.environment=e AND p.verified_at>=start_time AND p.verified_at<end_time AND(account IS NULL OR a.receiving_account_id=account) GROUP BY a.method)t),'[]'),
 'accounts',coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM(SELECT a.receiving_account_id account_id,a.method,r.display_suffix,sum(p.verified_amount_minor) amount_minor,count(*) payment_count FROM financial_payments p JOIN payment_attempts a ON a.id=p.attempt_id JOIN financial_receiving_accounts r ON r.id=a.receiving_account_id AND r.workspace_id=w AND r.environment=e WHERE p.workspace_id=w AND p.environment=e AND p.verified_at>=start_time AND p.verified_at<end_time AND(account IS NULL OR a.receiving_account_id=account) GROUP BY a.receiving_account_id,a.method,r.display_suffix ORDER BY 4 DESC)t),'[]'),
 'customers',coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM(SELECT c.id customer_id,c.reference,c.body->>'name' name,sum(x.amount_minor) amount_minor,count(DISTINCT p.id) payment_count FROM pg10_documents c JOIN pg10_documents d ON d.customer_id=c.id AND d.workspace_id=c.workspace_id AND d.environment=c.environment JOIN pg10_document_intents l ON l.document_id=d.id AND l.workspace_id=w AND l.environment=e JOIN financial_allocations x ON x.intent_id=l.intent_id AND x.workspace_id=w AND x.environment=e JOIN financial_payments p ON p.id=x.payment_id JOIN payment_attempts a ON a.id=p.attempt_id WHERE c.workspace_id=w AND c.environment=e AND c.kind='customers' AND p.verified_at>=start_time AND p.verified_at<end_time AND(account IS NULL OR a.receiving_account_id=account) GROUP BY c.id,c.reference,c.body->>'name' ORDER BY 4 DESC LIMIT 100)t),'[]'),
 'refunds',coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM(SELECT r.status,sum(r.amount_minor) amount_minor,count(*) request_count FROM pg11_refunds r JOIN financial_payments p ON p.id=r.payment_id JOIN payment_attempts a ON a.id=p.attempt_id WHERE r.workspace_id=w AND r.environment=e AND r.created_at>=start_time AND r.created_at<end_time AND(account IS NULL OR a.receiving_account_id=account) GROUP BY r.status)t),'[]'),
 'statement_links',jsonb_build_object('provenance','merchant_imported_statement','provider_verified',false,'amount_minor',coalesce((SELECT sum(s.amount_minor) FROM pg11_statements s WHERE s.workspace_id=w AND s.environment=e AND s.payment_id IS NOT NULL AND s.transaction_at>=start_time AND s.transaction_at<end_time AND(account IS NULL OR s.account_id=account)),0),'count',(SELECT count(*) FROM pg11_statements s WHERE s.workspace_id=w AND s.environment=e AND s.payment_id IS NOT NULL AND s.transaction_at>=start_time AND s.transaction_at<end_time AND(account IS NULL OR s.account_id=account))),
 'customers_limit',100,'customers_definition','Top 100 invoice-linked customers by verified allocation; not all payer identities.',
 'daily',coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM(SELECT (p.verified_at AT TIME ZONE 'UTC')::date AS "day",sum(p.verified_amount_minor) amount_minor FROM financial_payments p JOIN payment_attempts a ON a.id=p.attempt_id WHERE p.workspace_id=w AND p.environment=e AND p.verified_at>=start_time AND p.verified_at<end_time AND(account IS NULL OR a.receiving_account_id=account) GROUP BY 1 ORDER BY 1)t),'[]'));
END $$;
CREATE FUNCTION pg13_notification_list(w uuid,e text,actor uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN
 PERFORM pg06_scope(w,e);
 RETURN jsonb_build_object('items',coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM(SELECT n.id,n.type,n.resource_id,n.body,n.created_at,r.read_at FROM pg13_notifications n LEFT JOIN pg13_notification_reads r ON r.notification_id=n.id AND r.actor_id=actor WHERE n.workspace_id=w AND n.environment=e ORDER BY n.created_at DESC LIMIT 100)t),'[]'));
END $$;
CREATE FUNCTION pg13_notification_read(w uuid,e text,item uuid,actor uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN
 PERFORM pg06_scope(w,e);
 IF NOT EXISTS(SELECT 1 FROM pg13_notifications WHERE workspace_id=w AND environment=e AND id=item) THEN RAISE EXCEPTION 'notification missing' USING ERRCODE='P0002';END IF;
 INSERT INTO pg13_notification_reads(notification_id,actor_id,read_at) VALUES(item,actor,now()) ON CONFLICT(notification_id,actor_id) DO NOTHING;RETURN true;
END $$;
REVOKE ALL ON FUNCTION pg13_reports(uuid,text,timestamptz,timestamptz,uuid),pg13_notification_list(uuid,text,uuid),pg13_notification_read(uuid,text,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pg13_reports(uuid,text,timestamptz,timestamptz,uuid),pg13_notification_list(uuid,text,uuid),pg13_notification_read(uuid,text,uuid,uuid) TO ekmivo_finance_reader;
COMMIT;
